package in.tucor.api.buyer;import jakarta.persistence.*;import java.io.Serializable;import java.time.Instant;import java.util.UUID;import java.util.Objects;@Entity @Table(name="buyer_saved_listings") @IdClass(BuyerSavedListing.Key.class) public class BuyerSavedListing{@Id @Column(name="buyer_id")public UUID buyerId;@Id @Column(name="listing_id")public UUID listingId;@Column(name="created_at")public Instant createdAt;@PrePersist void create(){if(createdAt==null)createdAt=Instant.now();}public static class Key implements Serializable{public UUID buyerId;public UUID listingId;public Key(){}public Key(UUID b,UUID l){buyerId=b;listingId=l;}public boolean equals(Object o){return o instanceof Key k&&Objects.equals(buyerId,k.buyerId)&&Objects.equals(listingId,k.listingId);}public int hashCode(){return Objects.hash(buyerId,listingId);}}}